contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry that performs the property test
    function run(address caller, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        require(caller != address(0));
        // We will have this contract act as the msg.sender to c; the Checker deploys c with this contract as deployer
        // Precondition: ensure caller has enough collateral tokens and has approved c to transfer them is not enforceable here,
        // so we only assert a postcondition that either the call reverted or the expected effects hold.

        // Record whether the call reverts and any observable values after attempting requestLoan
        bool reverted;
        uint256 reqID;

        // Try to perform the requestLoan call. It will attempt to call collateral().safeTransferFrom(msg.sender,...)
        // where msg.sender is this contract. If it reverts (e.g., due to ERC20 transfer failure), we capture that.
        uint256 id = c.requestLoan(amount, interest, loanToCollateral, duration); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            // leave reqID as 0 if reverted
            reqID = 0;
        } else {
            reverted = false;
            reqID = id;
        }

        // If the call did not revert, then the requests[reqID].active must be true (a newly created request is active)
        // and isActive(reqID) should reflect that. Also, requestLoan emits and transfers collateral, but we cannot observe token balances here.
        // So assert: either reverted is true, or isActive(reqID) == true.
        assert(reverted || c.isActive(reqID));
    }

    receive() external payable {}
}

