// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(address caller, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) internal {
        vm.assume(caller != address(0));
        bool reverted;
        uint256 reqID;
        try c.requestLoan(amount, interest, loanToCollateral, duration) returns (uint256 id) {
            reverted = false;
            reqID = id;
        } catch {
            reverted = true;
            // leave reqID as 0 if reverted
            reqID = 0;
        }
        assertTrue(reverted || c.isActive(reqID));
    }

    function testFuzz_run(address caller, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public {
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(caller, amount, interest, loanToCollateral, duration);
    }

    receive() external payable {}
}
